use crate::packet::{Context,Cover};use crate::verifier;pub fn qualify(context:&Context,cover:&Cover){let c=&context.c;let (d,target,ell,sm,p,cc,k)=(context.d,context.target,context.ell,context.sm,c.fp.p,c.f.c[0],cover.k);assert!(verifier::verify(context,cover));assert!(crate::reference::verify(context,cover));let mut mutations=vec![];let mut b=cover.clone();b.branches.pop();mutations.push(b);let mut b=cover.clone();b.branches[1].0=b.branches[0].0;mutations.push(b);let mut b=cover.clone();b.branches[0].0=(b.branches[0].0+1)%ell;mutations.push(b);let mut b=cover.clone();b.context.target=c.add(&target,&d);mutations.push(b);let mut b=cover.clone();b.context.d=c.add(&d,&d);mutations.push(b);let mut b=cover.clone();b.context.ell+=2;mutations.push(b);let mut b=cover.clone();b.context.sm=(sm+1)%ell;mutations.push(b);let mut b=cover.clone();b.context.c.f.c[0]=(cc+1)%p;mutations.push(b);let mut b=cover.clone();b.z=1;mutations.push(b);let mut b=cover.clone();b.reps[0].1=(b.reps[0].1+1)%p;mutations.push(b);let mut b=cover.clone();b.primitives[0].points[0].1=(b.primitives[0].points[0].1+1)%p;mutations.push(b);let mut b=cover.clone();b.primitives[0].a=0;mutations.push(b);let mut b=cover.clone();b.primitives[0].t=p;mutations.push(b);let mut b=cover.clone();b.k=(k+1)%ell;mutations.push(b);let mut b=cover.clone();b.branches[0].1.w[0]=(b.branches[0].1.w[0]+1)%ell;mutations.push(b);let mut b=cover.clone();b.branches[0].1.excluded=!b.branches[0].1.excluded;mutations.push(b);let mut b=cover.clone();b.branches[0].1.w.pop();mutations.push(b);let mut b=cover.clone();b.branches[0].1.w[0]=ell;mutations.push(b);assert_eq!(mutations.len(),18);for b in mutations{assert!(!verifier::verify(&context,&b));assert!(!crate::reference::verify(&context,&b));}}